27	const CARD_HEIGHT = 3.4;
28	const CARD_WIDTH = CARD_HEIGHT * (16 / 9);
29	const MAX_PROOF_IMAGES = 12;
30	const FALLBACK_COUNT = 8;
31	const PLANET_RADIUS = 8.0;
32	const CARD_RING_MIN_RADIUS = PLANET_RADIUS * 1.55;
33	const FALLBACK_COLORS = [
34	  0x6644aa, 0x4488bb, 0x44aacc, 0x228866, 0x886622, 0xaa4466, 0x664488, 0x4466aa,
35	] as const;
36	
37	function computeRadius(cardCount: number): number {
38	  const minArc = CARD_WIDTH * 1.15;
39	  return Math.max(CARD_RING_MIN_RADIUS, (minArc * cardCount) / (2 * Math.PI));
40	}
