42	/**
43	 * Creates a PlaneGeometry whose vertices are bent cylindrically around the Y-axis,
44	 * so the card's edges curve inward toward the planet (local -Z = radially inward).
45	 * Each vertex at local x=lx is moved to arc position on a cylinder of curveRadius:
46	 *   newX = curveRadius * sin(lx / curveRadius)
47	 *   newZ = -curveRadius * (1 - cos(lx / curveRadius))   ← negative = toward planet
48	 */
49	function createCurvedCardGeometry(
50	  width: number,
51	  height: number,
52	  curveRadius: number,
53	): THREE.BufferGeometry {
54	  const geo = new THREE.PlaneGeometry(width, height, 20, 1);
55	  const pos = geo.attributes.position as THREE.BufferAttribute;
56	  for (let i = 0; i < pos.count; i++) {
57	    const lx = pos.getX(i);
58	    const dAngle = lx / curveRadius;
59	    pos.setX(i, curveRadius * Math.sin(dAngle));
60	    pos.setZ(i, -curveRadius * (1.0 - Math.cos(dAngle)));
61	  }
62	  pos.needsUpdate = true;
63	  geo.computeVertexNormals();
64	  return geo;
65	}
