67	function loadImageTexture(
68	  loader: THREE.TextureLoader,
69	  url: string,
70	): Promise<THREE.Texture | null> {
71	  return new Promise((resolve) => {
72	    loader.load(
73	      url,
74	      (texture) => {
75	        texture.minFilter = THREE.LinearFilter;
76	        texture.generateMipmaps = false;
77	        resolve(texture);
78	      },
79	      undefined,
80	      () => resolve(null),
81	    );
82	  });
83	}
