85	function createCardMaterial(
86	  texture: THREE.Texture | null,
87	  color: number,
88	): THREE.MeshBasicMaterial {
89	  const mat = new THREE.MeshBasicMaterial({
90	    map: texture ?? null,
91	    color: texture ? 0xffffff : color,
92	    side: THREE.DoubleSide,
93	  });
94	
95	  if (texture) {
96	    // Flip UV.x on back face so back-side texture is not mirrored
97	    mat.onBeforeCompile = (shader) => {
98	      shader.fragmentShader = shader.fragmentShader.replace(
99	        "vec4 sampledDiffuseColor = texture2D( map, vMapUv );",
100	        `vec2 _uv = gl_FrontFacing ? vMapUv : vec2(1.0 - vMapUv.x, vMapUv.y);
101	        vec4 sampledDiffuseColor = texture2D( map, _uv );`,
102	      );
103	    };
104	    mat.needsUpdate = true;
105	  }
106	
107	  return mat;
108	}
