110	function selectProofItems(items: WorkApiItem[], max: number): WorkApiItem[] {
111	  const awardedVideo = items.filter((i) => i.isAwarded && i.thumbnailVideo);
112	  const awardedImage = items.filter((i) => i.isAwarded && !i.thumbnailVideo && i.thumbnailImage);
113	  const otherVideo   = items.filter((i) => !i.isAwarded && i.thumbnailVideo);
114	  const otherImage   = items.filter((i) => !i.isAwarded && !i.thumbnailVideo && i.thumbnailImage);
115	
116	  const result: WorkApiItem[] = [...awardedVideo];
117	  if (result.length < max) result.push(...awardedImage);
118	  if (result.length < max) result.push(...otherVideo);
119	  if (result.length < max) result.push(...otherImage);
120	  return result.slice(0, max);
121	}
