123	export class AboutProofRenderer {
124	  private _renderer: THREE.WebGLRenderer | null = null;
125	  private _scene: THREE.Scene | null = null;
126	  private _camera: THREE.PerspectiveCamera | null = null;
127	  private _group: THREE.Group | null = null;
128	  private _planetGroup: THREE.Group | null = null;
129	  private _geometries: THREE.BufferGeometry[] = [];
130	  private _materials: THREE.Material[] = [];
131	  private _textures: THREE.Texture[] = [];
132	  private _videoElements: HTMLVideoElement[] = [];
133	  private _rafId: number | null = null;
134	  private _resizeObserver: ResizeObserver | null = null;
135	  private _intersectionObserver: IntersectionObserver | null = null;
136	  private _rendering = false;
137	  private _disposed = false;
138	  private _canvas: HTMLCanvasElement | null = null;
139	  private _scrollProgress = 0;
140	  private _rotationStrategy: ProofRotationStrategy;
141	
142	  constructor(rotationStrategy?: ProofRotationStrategy) {
143	    this._rotationStrategy =
144	      rotationStrategy ?? new ScrollAcceleratingRotation(DEFAULT_SCROLL_ACCELERATING_CONFIG);
145	  }
146	
147	  setScrollProgress(progress: number): void {
148	    const prev = this._scrollProgress;
149	    this._scrollProgress = Math.max(0, Math.min(1, progress));
150	    this._rotationStrategy.feed(this._scrollProgress, Math.abs(this._scrollProgress - prev));
151	  }
