153	  async init(canvas: HTMLCanvasElement): Promise<void> {
154	    this._canvas = canvas;
155	
156	    const renderer = new THREE.WebGLRenderer({ canvas, antialias: true, alpha: true });
157	    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
158	    renderer.setClearAlpha(0);
159	    this._renderer = renderer;
160	
161	    const scene = new THREE.Scene();
162	    this._scene = scene;
163	
164	    const w = Math.max(canvas.clientWidth, 1);
165	    const h = Math.max(canvas.clientHeight, 1);
166	    const camera = new THREE.PerspectiveCamera(65, w / h, 0.1, 1000);
167	    camera.position.set(0, 3, 22);
168	    camera.lookAt(0, 0, 0);
169	    this._camera = camera;
170	
171	    scene.add(new THREE.AmbientLight(0x8ea8d8, 0.28));
172	
173	    const keyLight = new THREE.SpotLight(0xdfe8ff, 2.8);
174	    keyLight.position.set(14, 20, 10);
175	    keyLight.angle = 0.30;
176	    keyLight.penumbra = 0.52;
177	    keyLight.decay = 1.35;
178	    keyLight.distance = 60;
179	    scene.add(keyLight);
180	    scene.add(keyLight.target);
181	
182	    const fillLight = new THREE.DirectionalLight(0xa9c2ff, 0.55);
183	    fillLight.position.set(-20, 14, 20);
184	    scene.add(fillLight);
185	
186	    const rimLight = new THREE.SpotLight(0x9fb7ff, 0.20);
187	    rimLight.position.set(-10, 8, -14);
188	    rimLight.angle = 0.20;
189	    rimLight.penumbra = 0.90;
190	    rimLight.decay = 1.4;
191	    rimLight.distance = 45;
192	    scene.add(rimLight);
193	    scene.add(rimLight.target);
194	
195	    const group = new THREE.Group();
196	    this._group = group;
197	    scene.add(group);
198	
199	    // Fetch works and planet textures in parallel
200	    const [worksResult, planetGroup] = await Promise.all([
201	      fetchWorksList(0, MAX_PROOF_IMAGES, null, undefined, true).catch(() => null),
202	      this._buildPlanet(),
203	    ]);
204	
205	    if (this._disposed) return;
206	
207	    if (planetGroup) {
208	      this._planetGroup = planetGroup;
209	      scene.add(planetGroup);
210	    }
211	
212	    const items = worksResult ? selectProofItems(worksResult.items, MAX_PROOF_IMAGES) : [];
213	
214	    if (items.length > 0) {
215	      const loader = new THREE.TextureLoader();
216	      const textures = await Promise.all(
217	        items.map((item) => this._loadItemMedia(loader, item)),
218	      );
219	      if (this._disposed) return;
220	      const radius = computeRadius(textures.length);
221	      textures.forEach((texture, i) => {
222	        if (texture) this._textures.push(texture);
223	        this._addCard(group, i, textures.length, texture, radius);
224	      });
225	    } else {
226	      const radius = computeRadius(FALLBACK_COUNT);
227	      for (let i = 0; i < FALLBACK_COUNT; i++) {
228	        this._addCard(group, i, FALLBACK_COUNT, null, radius);
229	      }
230	    }
231	
232	    this._syncSize();
233	    this._observeResize();
234	    this._observeVisibility();
235	  }
236	
237	  dispose(): void {
238	    this._disposed = true;
239	    this._stopRaf();
240	
241	    this._resizeObserver?.disconnect();
242	    this._resizeObserver = null;
243	
244	    this._intersectionObserver?.disconnect();
245	    this._intersectionObserver = null;
246	
247	    this._geometries.forEach((g) => g.dispose());
248	    this._geometries = [];
249	
250	    this._materials.forEach((m) => m.dispose());
251	    this._materials = [];
252	
253	    this._textures.forEach((t) => t.dispose());
254	    this._textures = [];
255	
256	    this._videoElements.forEach((v) => {
257	      v.pause();
258	      v.src = "";
259	      v.load();
260	    });
261	    this._videoElements = [];
262	
263	    this._renderer?.dispose();
264	    this._renderer?.forceContextLoss();
265	    this._renderer = null;
266	    this._scene = null;
267	    this._camera = null;
268	    this._group = null;
269	    this._planetGroup = null;
270	    this._canvas = null;
271	  }
