273	  private async _buildPlanet(): Promise<THREE.Group | null> {
274	    const loader = new THREE.TextureLoader();
275	    try {
276	      const [dayMap, bumpMap] = await Promise.all([
277	        new Promise<THREE.Texture>((res, rej) =>
278	          loader.load("/resource/images/texture/moon/moonmap4k.jpg", res, undefined, rej),
279	        ),
280	        new Promise<THREE.Texture>((res, rej) =>
281	          loader.load("/resource/images/texture/moon/moonbump4k.jpg", res, undefined, rej),
282	        ),
283	      ]);
284	
285	      if (this._disposed) {
286	        dayMap.dispose();
287	        bumpMap.dispose();
288	        return null;
289	      }
290	
291	      dayMap.colorSpace = THREE.SRGBColorSpace;
292	      this._textures.push(dayMap, bumpMap);
293	
294	      const geo = new THREE.SphereGeometry(PLANET_RADIUS, 48, 32);
295	      const mat = new THREE.MeshStandardMaterial({
296	        map: dayMap,
297	        bumpMap,
298	        bumpScale: 0.022,
299	        roughness: 0.35,
300	        metalness: 0.05,
301	      });
302	      this._geometries.push(geo);
303	      this._materials.push(mat);
304	      const mesh = new THREE.Mesh(geo, mat);
305	
306	      const atmGeo = new THREE.SphereGeometry(PLANET_RADIUS * 1.16, 48, 32);
307	      const atmMat = new THREE.ShaderMaterial({
308	        vertexShader: atmosphereVertexShader as string,
309	        fragmentShader: PLANET_ATMOSPHERE_FRAGMENT,
310	        uniforms: {
311	          atmOpacity: { value: 0.58 },
312	          atmPowFactor: { value: 4.3 },
313	          atmMultiplier: { value: 8.4 },
314	          atmColor: { value: new THREE.Color(0.92, 0.96, 1.0) },
315	        },
316	        blending: THREE.AdditiveBlending,
317	        side: THREE.BackSide,
318	        transparent: true,
319	        depthWrite: false,
320	      });
321	      this._geometries.push(atmGeo);
322	      this._materials.push(atmMat);
323	      const atmMesh = new THREE.Mesh(atmGeo, atmMat);
324	
325	      const group = new THREE.Group();
326	      group.add(mesh);
327	      group.add(atmMesh);
328	      return group;
329	    } catch {
330	      return null;
331	    }
332	  }
