334	  private _createVideoElement(url: string): HTMLVideoElement {
335	    const video = document.createElement("video");
336	    video.src = url;
337	    video.loop = true;
338	    video.muted = true;
339	    video.playsInline = true;
340	    video.crossOrigin = "anonymous";
341	    void video.play();
342	    this._videoElements.push(video);
343	    return video;
344	  }
345	
346	  private _createVideoTexture(video: HTMLVideoElement): THREE.VideoTexture {
347	    const texture = new THREE.VideoTexture(video);
348	    texture.minFilter = THREE.LinearFilter;
349	    texture.magFilter = THREE.LinearFilter;
350	    texture.generateMipmaps = false;
351	    return texture;
352	  }
353	
354	  private async _loadItemMedia(
355	    loader: THREE.TextureLoader,
356	    item: WorkApiItem,
357	  ): Promise<THREE.Texture | null> {
358	    if (item.thumbnailVideo) {
359	      const video = this._createVideoElement(item.thumbnailVideo);
360	      return this._createVideoTexture(video);
361	    }
362	    const imageUrl = item.thumbnailImage;
363	    if (imageUrl) {
364	      return loadImageTexture(loader, imageUrl);
365	    }
366	    return null;
367	  }
368	
369	  private _addCard(
370	    group: THREE.Group,
371	    index: number,
372	    total: number,
373	    texture: THREE.Texture | null,
374	    radius: number,
375	  ): void {
376	    const angle = (index / total) * Math.PI * 2;
377	    const x = radius * Math.cos(angle);
378	    const z = radius * Math.sin(angle);
379	
380	    const geo = createCurvedCardGeometry(CARD_WIDTH, CARD_HEIGHT, radius);
381	    this._geometries.push(geo);
382	
383	    const mat = createCardMaterial(
384	      texture,
385	      FALLBACK_COLORS[index % FALLBACK_COLORS.length],
386	    );
387	    this._materials.push(mat);
388	
389	    const mesh = new THREE.Mesh(geo, mat);
390	    mesh.position.set(x, 0, z);
391	    // rotation.y so the front face (+Z normal) points radially outward from center
392	    mesh.rotation.y = Math.PI / 2 - angle;
393	    group.add(mesh);
394	  }
395	
396	  private readonly _tick = (): void => {
397	    if (this._disposed || !this._rendering) return;
398	    const p = this._scrollProgress;
399	    const speed = this._rotationStrategy.next();
400	    if (this._group) this._group.rotation.y += speed;
401	    // Planet counter-rotates slowly, independent of card ring
402	    if (this._planetGroup) this._planetGroup.rotation.y += 0.0003;
403	    if (this._camera) {
404	      this._camera.position.y = 3 - p * 3;
405	      this._camera.lookAt(0, 0, 0);
406	    }
407	    if (this._renderer && this._scene && this._camera) {
408	      this._renderer.render(this._scene, this._camera);
409	    }
410	    this._rafId = requestAnimationFrame(this._tick);
411	  };
412	
413	  private _startRaf(): void {
414	    if (this._rafId !== null || this._disposed) return;
415	    this._rendering = true;
416	    this._rafId = requestAnimationFrame(this._tick);
417	  }
418	
419	  private _stopRaf(): void {
420	    this._rendering = false;
421	    if (this._rafId !== null) {
422	      cancelAnimationFrame(this._rafId);
423	      this._rafId = null;
424	    }
425	  }
426	
427	  private _syncSize(): void {
428	    const canvas = this._canvas;
429	    const renderer = this._renderer;
430	    const camera = this._camera;
431	    if (!canvas || !renderer || !camera) return;
432	    const w = canvas.clientWidth;
433	    const h = canvas.clientHeight;
434	    if (w <= 0 || h <= 0) return;
435	    renderer.setSize(w, h, false);
436	    camera.aspect = w / h;
437	    camera.updateProjectionMatrix();
438	  }
439	
440	  private _observeResize(): void {
441	    if (!this._canvas) return;
442	    this._resizeObserver = new ResizeObserver(() => this._syncSize());
443	    this._resizeObserver.observe(this._canvas);
444	  }
445	
446	  private _observeVisibility(): void {
447	    if (!this._canvas) return;
448	    this._intersectionObserver = new IntersectionObserver(
449	      (entries) => {
450	        if (entries[0]?.isIntersecting) {
451	          this._startRaf();
452	        } else {
453	          this._stopRaf();
454	        }
455	      },
456	      { threshold: 0 },
457	    );
458	    this._intersectionObserver.observe(this._canvas);
459	  }
460	}
