107	function loadTexture(
108	  loader: THREE.TextureLoader,
109	  url: string,
110	  renderer: THREE.WebGLRenderer,
111	): Promise<THREE.Texture | null> {
112	  return new Promise((resolve) => {
113	    loader.load(
114	      url,
115	      (texture) => {
116	        texture.minFilter = THREE.LinearMipmapLinearFilter;
117	        texture.magFilter = THREE.LinearFilter;
118	        texture.generateMipmaps = true;
119	        texture.anisotropy = renderer.capabilities.getMaxAnisotropy();
120	        resolve(texture);
121	      },
122	      undefined,
123	      () => resolve(null),
124	    );
125	  });
126	}
127	
128	function computeOpacity(n: number): number {
129	  if (n < FADE_IN_START) return 0;
130	  if (n < FADE_IN_END) return (n - FADE_IN_START) / (FADE_IN_END - FADE_IN_START);
131	  if (n < FADE_OUT_START) return 1;
132	  if (n < FADE_OUT_END) return 1 - (n - FADE_OUT_START) / (FADE_OUT_END - FADE_OUT_START);
133	  return 0;
134	}
135	
136	function computeBlur(n: number): number {
137	  if (n < BLUR_IN_START) return MAX_BLUR;
138	  if (n < BLUR_IN_END) return MAX_BLUR * (1 - (n - BLUR_IN_START) / (BLUR_IN_END - BLUR_IN_START));
139	  if (n < BLUR_OUT_START) return 0;
140	  if (n < BLUR_OUT_END) return MAX_BLUR * ((n - BLUR_OUT_START) / (BLUR_OUT_END - BLUR_OUT_START));
141	  return MAX_BLUR;
142	}
