161	export class InfiniteGalleryRenderer {
162	  private _renderer: THREE.WebGLRenderer | null = null;
163	  private _scene: THREE.Scene | null = null;
164	  private _camera: THREE.PerspectiveCamera | null = null;
165	  private _clock: THREE.Clock | null = null;
166	  private _raycaster: THREE.Raycaster | null = null;
167	  private _canvas: HTMLCanvasElement | null = null;
168	
169	  private _planes: PlaneRecord[] = [];
170	  private _meshList: THREE.Object3D[] = [];
171	  private _textures: (THREE.Texture | null)[] = [];
172	  private _geometries: THREE.BufferGeometry[] = [];
173	  private _materials: THREE.ShaderMaterial[] = [];
174	
175	  private _rafId: number | null = null;
176	  private _rendering = false;
177	  private _disposed = false;
178	
179	  private _resizeObserver: ResizeObserver | null = null;
180	  private _intersectionObserver: IntersectionObserver | null = null;
181	
182	  private _scrollVelocity = 0;
183	  private _lastInteractionMs = 0;
184	  private _isAutoPlaying = false;
185	  private _galleryEnabled = false;
186	  private _imageCount = 0;
187	  private _autoPlayIntervalId: ReturnType<typeof setInterval> | null = null;
188	  private _hoveredIndex = -1;
189	  private _touchLastY = 0;
190	
191	  private readonly _pointerNDC = new THREE.Vector2();
192	
193	  private readonly _onWheel: (e: WheelEvent) => void;
194	  private readonly _onKeyDown: (e: KeyboardEvent) => void;
195	  private readonly _onTouchStart: (e: TouchEvent) => void;
196	  private readonly _onTouchMove: (e: TouchEvent) => void;
197	  private readonly _onPointerMove: (e: PointerEvent) => void;
198	  private readonly _onPointerLeave: (e: PointerEvent) => void;
199	
200	  constructor() {
201	    this._onWheel = (e) => {
202	      e.preventDefault();
203	      this._recordInteraction();
204	      this._scrollVelocity += e.deltaY * 0.01 * SCROLL_SPEED;
205	      this._scrollVelocity = Math.max(-MAX_SCROLL_VEL, Math.min(MAX_SCROLL_VEL, this._scrollVelocity));
206	    };
207	    this._onKeyDown = (e) => {
208	      if (e.key === "ArrowDown" || e.key === "ArrowRight") {
209	        this._recordInteraction();
210	        this._scrollVelocity += 2 * SCROLL_SPEED;
211	      } else if (e.key === "ArrowUp" || e.key === "ArrowLeft") {
212	        this._recordInteraction();
213	        this._scrollVelocity -= 2 * SCROLL_SPEED;
214	      }
215	    };
216	    this._onTouchStart = (e) => {
217	      if (e.touches[0]) this._touchLastY = e.touches[0].clientY;
218	      this._recordInteraction();
219	    };
220	    this._onTouchMove = (e) => {
221	      e.preventDefault();
222	      if (!e.touches[0]) return;
223	      const y = e.touches[0].clientY;
224	      const delta = this._touchLastY - y;
225	      this._touchLastY = y;
226	      this._recordInteraction();
227	      this._scrollVelocity += delta * 0.03 * SCROLL_SPEED;
228	      this._scrollVelocity = Math.max(-MAX_SCROLL_VEL, Math.min(MAX_SCROLL_VEL, this._scrollVelocity));
229	    };
230	    this._onPointerMove = (e) => {
231	      const canvas = this._canvas;
232	      const camera = this._camera;
233	      const raycaster = this._raycaster;
234	      if (!canvas || !camera || !raycaster) return;
235	      const rect = canvas.getBoundingClientRect();
236	      this._pointerNDC.set(
237	        ((e.clientX - rect.left) / rect.width) * 2 - 1,
238	        -((e.clientY - rect.top) / rect.height) * 2 + 1,
239	      );
240	      raycaster.setFromCamera(this._pointerNDC, camera);
241	      const intersects = raycaster.intersectObjects(this._meshList, false);
242	      if (intersects.length > 0) {
243	        const hit = intersects[0]?.object;
244	        this._hoveredIndex = this._planes.findIndex((r) => r.mesh === hit);
245	      } else {
246	        this._hoveredIndex = -1;
247	      }
248	    };
249	    this._onPointerLeave = (_e) => {
250	      this._hoveredIndex = -1;
251	    };
252	  }
