2	  feed(scrollProgress: number, scrollDelta: number): void;
3	  next(): number;
4	}
5	
6	export interface ScrollAcceleratingConfig {
7	  baseSpeed: number;
8	  progressScale: number;
9	  velocityScale: number;
10	  decayFactor: number;
11	}
12	
13	export const DEFAULT_SCROLL_ACCELERATING_CONFIG: ScrollAcceleratingConfig = {
14	  baseSpeed: 0.0005,
15	  progressScale: 1.8,
16	  velocityScale: 100,
17	  decayFactor: 0.88,
18	};
19	
20	export class ScrollAcceleratingRotation implements ProofRotationStrategy {
21	  private _progress = 0;
22	  private _velocity = 0;
23	
24	  constructor(private readonly _cfg: ScrollAcceleratingConfig) {}
25	
26	  feed(progress: number, delta: number): void {
27	    this._progress = progress;
28	    this._velocity += delta;
29	  }
30	
31	  next(): number {
32	    this._velocity *= this._cfg.decayFactor;
33	    return (
34	      this._cfg.baseSpeed *
35	      (1 + this._progress * this._cfg.progressScale + this._velocity * this._cfg.velocityScale)
36	    );
37	  }
38	}
