210	
211	function _rangeAlpha(p: number, inStart: number, inEnd: number, outStart: number, outEnd: number): number {
212	  if (p < inStart) return 0;
213	  if (p < inEnd) return _easeInOut(_clamp01((p - inStart) / (inEnd - inStart)));
214	  if (p < outStart) return 1;
215	  if (p < outEnd) return _easeInOut(_clamp01(1 - (p - outStart) / (outEnd - outStart)));
216	  return 0;
217	}
