63	function resolveDebugProgressBucket(progress: number): number {
64	  return Math.max(
65	    0,
66	    Math.min(
67	      DEBUG_PROGRESS_BUCKETS,
68	      Math.round(Math.max(0, Math.min(1, progress)) * DEBUG_PROGRESS_BUCKETS),
69	    ),
70	  );
71	}
