73	function shouldLogDebugBucket(
74	  map: Map<AboutSceneSectionKey, string>,
75	  sceneKey: AboutSceneSectionKey,
76	  phase: string,
77	  progress: number,
78	  sheetId?: AboutTheatreSheetId | null,
79	): boolean {
80	  const bucket = resolveDebugProgressBucket(progress);
81	  const nextKey = `${phase}:${sheetId ?? "none"}:${bucket}`;
82	  const previousKey = map.get(sceneKey) ?? null;
83	  if (previousKey === nextKey) return false;
84	  map.set(sceneKey, nextKey);
85	  return true;
86	}
