88	function normalizeAboutTheatreState(
89	  savedState: Record<string, unknown>,
90	): Record<string, unknown> {
91	  const migratedState = migrateLegacyAboutTheatreState(savedState);
92	  const sheetsById = readAboutRecord(migratedState.sheetsById);
93	  const cameraSheet = readAboutRecord(sheetsById?.heroIntro);
94	  const sequence = readAboutRecord(cameraSheet?.sequence);
95	  const staticOverrides = readAboutRecord(sequence?.staticOverrides);
96	  const objectsByKey = readAboutRecord(staticOverrides?.byObject);
97	  const cameraObject = readAboutRecord(objectsByKey?.[ABOUT_THEATRE_OBJECT_ID]);
98	
99	  if (cameraObject) {
100	    const mergedValues = mergeAboutSceneState(
101	      cameraObject as Partial<typeof ABOUT_DEFAULT_SCENE_STATE>,
102	    );
103	    Object.assign(cameraObject, pickAboutTheatreValue(mergedValues));
104	  }
105	
106	  const projectDefinition = readAboutRecord(
107	    migratedState.definitionVersion != null ? migratedState : null,
108	  );
109	  if (!projectDefinition || !projectDefinition.addressesBySheetId) {
110	    return migratedState;
111	  }
112	  return {
113	    ...migratedState,
114	    projectId: ABOUT_THEATRE_PROJECT_ID,
115	  };
116	}
