118	function migrateLegacyAboutTheatreState(
119	  savedState: Record<string, unknown>,
120	): Record<string, unknown> {
121	  const sheetsById = readAboutRecord(savedState.sheetsById);
122	  if (!sheetsById) {
123	    return savedState;
124	  }
125	  const nextSheetsById: Record<string, unknown> = {};
126	  let didChange = false;
127	
128	  Object.entries(sheetsById).forEach(([sheetId, sheetState]) => {
129	    const mappedSheetId =
130	      LEGACY_ABOUT_SHEET_ID_MAP[sheetId as LegacyAboutSheetId] ?? sheetId;
131	    if (mappedSheetId !== sheetId) {
132	      didChange = true;
133	    }
134	    if ((ABOUT_THEATRE_SHEET_IDS as readonly string[]).includes(mappedSheetId)) {
135	      nextSheetsById[mappedSheetId] = sheetState;
136	      return;
137	    }
138	    didChange = true;
139	  });
140	
141	  if (!didChange) {
142	    return savedState;
143	  }
144	
145	  return {
146	    ...savedState,
147	    sheetsById: nextSheetsById,
148	  };
149	}
