158	function mergeAboutTheatreStateSources(
159	  fileState: Record<string, unknown> | null,
160	  savedState: Record<string, unknown> | null,
161	): Record<string, unknown> | null {
162	  if (!fileState) return savedState;
163	  if (!savedState) return fileState;
164	  const fileSheetsById = readAboutRecord(fileState.sheetsById) ?? {};
165	  const savedSheetsById = readAboutRecord(savedState.sheetsById) ?? {};
166	  return {
167	    ...fileState,
168	    ...savedState,
169	    sheetsById: {
170	      ...fileSheetsById,
171	      ...savedSheetsById,
172	    },
173	  };
