215	        },
216	      );
217	      const sequenceLength = this._resolveSheetLength(sheetId, sheet.sequence);
218	      const playbackRange = this._resolvePreviewRange(sheetId, sequenceLength);
219	      this._objectBySheetId.set(sheetId, object);
220	      this._sequenceBySheetId.set(sheetId, sheet.sequence);
221	      this._lengthBySheetId.set(sheetId, sequenceLength);
