228	  static getInstance(): AboutTheatreRuntime {
229	    if (AboutTheatreRuntime._instance) return AboutTheatreRuntime._instance;
230	    AboutTheatreRuntime._instance = new AboutTheatreRuntime();
231	    return AboutTheatreRuntime._instance;
