233	
234	  readState(sheetId: AboutTheatreSheetId, position = 0): AboutTheatreValue {
235	    const sequence = this._sequenceBySheetId.get(sheetId);
236	    const object = this._objectBySheetId.get(sheetId);
237	    if (!sequence || !object)
238	      return pickAboutTheatreValue(cloneAboutSceneState(ABOUT_DEFAULT_SCENE_STATE));
239	    const previousPosition = sequence.position;
240	    sequence.position = this._clampPosition(
241	      position,
242	      this._lengthBySheetId.get(sheetId) ?? 0,
243	    );
244	    const state = mergeAboutTheatreValue(object.value);
245	    sequence.position = previousPosition;
246	    return pickAboutTheatreValue(state);
247	  }
248	
249	  resolveSceneProgressState(
250	    sceneKey: AboutSceneSectionKey,
251	    progress: number,
252	  ): AboutSceneProgressState | null {
253	    const resolvedSteps = this._resolveSceneSteps(sceneKey)
254	      .map((step) => this._resolveStep(step))
255	      .filter((step): step is AboutResolvedTheatrePlaybackStep => step != null);
256	    if (resolvedSteps.length === 0) {
257	      if (DEBUG_SCENE_KEYS.includes(sceneKey)) {
258	        Logger.warn(CLASS, "resolveSceneProgressState", "No theatre steps resolved.", {
259	          sceneKey,
260	          progress,
261	        });
262	      }
263	      return null;
264	    }
265	    const clampedProgress = this._clampPosition(progress, 1);
266	    for (const step of resolvedSteps) {
267	      if (!this._isProgressWithinRange(clampedProgress, step.progressRange)) {
268	        continue;
269	      }
270	      const nextState = {
271	        sheetId: step.sheetId,
272	        localProgress: this._resolveLocalProgress(
273	          clampedProgress,
274	          step.progressRange,
275	        ),
276	      };
277	      return nextState;
278	    }
279	    if (
280	      DEBUG_SCENE_KEYS.includes(sceneKey) &&
281	      shouldLogDebugBucket(
282	        debugResolveLogKeyByScene,
283	        sceneKey,
284	        "resolve-miss",
285	        progress,
286	      )
287	    ) {
288	      Logger.warn(
289	        CLASS,
290	        "resolveSceneProgressState",
291	        "Resolved steps exist but none matched current progress.",
292	        {
293	          sceneKey,
294	          progress,
295	          clampedProgress,
296	          resolvedSteps,
297	        },
298	      );
299	    }
300	    return null;
301	  }
302	
303	  resolveSceneState(
304	    sceneKey: AboutSceneSectionKey,
305	    progress: number,
306	  ): AboutTheatreValue | null {
307	    const state = this.resolveSceneProgressState(sceneKey, progress);
308	    if (!state) return null;
309	    const range = this._resolvePlaybackRange(
310	      state.sheetId,
311	      this._lengthBySheetId.get(state.sheetId) ?? 0,
312	    );
313	    const position =
314	      range.start +
315	      (range.end - range.start) * this._clampPosition(state.localProgress, 1);
316	    return this.readState(state.sheetId, position);
317	  }
