352	  private _startSheetAutoplay(
353	    engine: Engine,
354	    sheetId: AboutTheatreSheetId,
355	    rate: number,
356	  ): Promise<void> {
357	    return this._autoplayRuntime.startSheetAutoplay(engine, {
