374	  syncSceneToEngine(
375	    engine: Engine,
376	    sceneKey: AboutSceneSectionKey,
377	    progress: number,
378	  ): AboutSceneProgressState | null {
379	    const resolvedState = this.resolveSceneState(sceneKey, progress);
380	    const progressState = this.resolveSceneProgressState(sceneKey, progress);
381	    if (
382	      DEBUG_SCENE_KEYS.includes(sceneKey) &&
383	      shouldLogDebugBucket(
384	        debugSyncLogKeyByScene,
385	        sceneKey,
386	        "sync",
387	        progress,
388	        progressState?.sheetId ?? null,
389	      )
390	    ) {
391	      const range =
392	        progressState == null
393	          ? null
394	          : this._resolvePlaybackRange(
395	              progressState.sheetId,
396	              this._lengthBySheetId.get(progressState.sheetId) ?? 0,
397	            );
398	      const position =
399	        progressState == null || range == null
400	          ? null
401	          : range.start +
402	            (range.end - range.start) * this._clampPosition(progressState.localProgress, 1);
403	    }
404	    this._rig.apply(
405	      engine,
406	      mergeAboutTheatreValue(resolvedState ?? pickAboutTheatreValue(ABOUT_DEFAULT_SCENE_STATE)),
407	    );
408	    return progressState;
409	  }
410	
411	  private _resolvePlaybackRange(
412	    sheetId: AboutTheatreSheetId,
413	    length: number,
414	  ): AboutTheatrePlaybackRange {
415	    const configuredRange = this._playbackRangeBySheetId.get(sheetId) ?? null;
416	    if (configuredRange) {
417	      return {
418	        start: this._clampPosition(configuredRange.start, length),
419	        end: this._clampPosition(configuredRange.end, length),
420	      };
421	    }
422	    return {
423	      start: 0,
424	      end: Number.isFinite(length) && length > 0 ? length : 0,
425	    };
426	  }
427	
428	  private _resolveSheetLength(
429	    sheetId: AboutTheatreSheetId,
430	    sequence: TheatreSequencePort,
431	  ): number {
432	    const directLength =
433	      typeof sequence.length === "number" ? sequence.length : null;
434	    if (
435	      directLength != null &&
436	      Number.isFinite(directLength) &&
437	      directLength > 0
438	    ) {
439	      return directLength;
440	    }
441	    const stateLength = this._readSheetLengthFromState(sheetId);
442	    if (stateLength > 0) return stateLength;
443	    return 0;
444	  }
