446	  private _resolveSceneSteps(
447	    sceneKey: AboutSceneSectionKey,
448	  ): readonly AboutTheatrePlaybackStep[] {
449	    return ABOUT_SCENE_THEATRE_STEPS[sceneKey] ?? [];
450	  }
451	
452	  private _resolveStep(
453	    step: AboutTheatrePlaybackStep,
454	  ): AboutResolvedTheatrePlaybackStep | null {
455	    const sequence = this._sequenceBySheetId.get(step.sheetId);
456	    if (!sequence) return null;
457	    const length = this._lengthBySheetId.get(step.sheetId) ?? 0;
458	    return {
459	      sheetId: step.sheetId,
460	      range: this._resolveConfiguredPlaybackRange(
461	        step.playbackRange,
462	        step.sheetId,
463	        length,
464	      ),
465	      progressRange: this._resolveProgressRange(step.progressRange),
466	    };
467	  }
468	
469	  private _resolveConfiguredPlaybackRange(
470	    configuredRange: AboutTheatrePlaybackRange | undefined,
471	    sheetId: AboutTheatreSheetId,
472	    length: number,
473	  ): AboutTheatrePlaybackRange {
474	    if (!configuredRange) {
475	      return this._resolvePlaybackRange(sheetId, length);
476	    }
477	    return {
478	      start: this._clampPosition(configuredRange.start, length),
479	      end: this._clampPosition(configuredRange.end, length),
480	    };
481	  }
482	
483	  private _resolveProgressRange(
484	    progressRange: AboutSceneProgressRange | undefined,
485	  ): AboutSceneProgressRange {
486	    if (!progressRange) {
487	      return { start: 0, end: 1 };
488	    }
489	    const start = this._clampPosition(progressRange.start, 1);
490	    const end = this._clampPosition(progressRange.end, 1);
491	    if (end <= start) {
492	      return { start, end: 1 };
493	    }
494	    return { start, end };
495	  }
496	
497	  private _isProgressWithinRange(
498	    progress: number,
499	    range: AboutSceneProgressRange,
500	  ): boolean {
501	    if (progress < range.start) return false;
502	    if (progress > range.end && range.end < 1) return false;
503	    return true;
504	  }
505	
506	  private _resolveLocalProgress(
507	    progress: number,
508	    range: AboutSceneProgressRange,
509	  ): number {
510	    const span = Math.max(range.end - range.start, Number.EPSILON);
511	    return this._clampPosition((progress - range.start) / span, 1);
512	  }
