514	  private _readSheetLengthFromState(sheetId: AboutTheatreSheetId): number {
515	    const sheetsById = readAboutRecord(this._stateSource.sheetsById);
516	    if (!sheetsById) return 0;
517	    const sheetState = readAboutRecord(sheetsById[sheetId]);
518	    if (!sheetState) return 0;
519	    const sequence = readAboutRecord(sheetState.sequence);
520	    if (!sequence) return 0;
521	    const length = sequence.length;
522	    if (typeof length !== "number" || !Number.isFinite(length) || length <= 0) {
523	      return 0;
524	    }
525	    return length;
526	  }
527	
528	  private _clampPosition(position: number, length: number): number {
529	    if (!Number.isFinite(length) || length <= 0) return 0;
530	    if (!Number.isFinite(position)) return 0;
531	    if (position <= 0) return 0;
532	    if (position >= length) return length;
533	    return position;
534	  }
