536	  private _syncSheetState(
537	    engine: Engine,
538	    sheetId: AboutTheatreSheetId,
539	    position: number,
540	  ): void {
541	    this._rig.apply(engine, mergeAboutTheatreValue(this.readState(sheetId, position)));
542	  }
543	
544	  private _resolvePreviewRange(
545	    sheetId: AboutTheatreSheetId,
546	    sheetLength: number,
547	  ): AboutTheatrePlaybackRange | null {
548	    const tracksByObject = this._readSheetTracksByObject(sheetId);
549	    const objectTracks = tracksByObject?.[ABOUT_THEATRE_OBJECT_ID];
550	    if (!objectTracks || typeof objectTracks !== "object") return null;
551	    const trackData = (objectTracks as Record<string, unknown>).trackData;
552	    if (!trackData || typeof trackData !== "object") return null;
553	    let minPosition = Number.POSITIVE_INFINITY;
554	    let maxPosition = Number.NEGATIVE_INFINITY;
555	    Object.values(trackData as Record<string, unknown>).forEach(
556	      (trackState) => {
557	        if (!trackState || typeof trackState !== "object") return;
558	        const keyframes = (trackState as Record<string, unknown>).keyframes;
559	        if (!Array.isArray(keyframes)) return;
560	        const positionedKeyframes = keyframes
561	          .map((keyframe) => {
562	            if (!keyframe || typeof keyframe !== "object") return null;
563	            const position = (keyframe as Record<string, unknown>).position;
564	            return typeof position === "number" ? position : null;
565	          })
566	          .filter(
567	            (position): position is number =>
568	              typeof position === "number" && Number.isFinite(position),
569	          );
570	        if (positionedKeyframes.length < 2) return;
571	        minPosition = Math.min(minPosition, ...positionedKeyframes);
572	        maxPosition = Math.max(maxPosition, ...positionedKeyframes);
573	      },
574	    );
575	    if (!Number.isFinite(minPosition) || !Number.isFinite(maxPosition)) {
576	      return null;
577	    }
578	    if (maxPosition <= minPosition) {
579	      return null;
580	    }
581	    return {
582	      start: this._clampPosition(minPosition, sheetLength),
583	      end: this._clampPosition(maxPosition, sheetLength),
584	    };
585	  }
586	
587	  private _readSheetTracksByObject(
588	    sheetId: AboutTheatreSheetId,
589	  ): Record<string, unknown> | null {
590	    const sheetsById = readAboutRecord(this._stateSource.sheetsById);
591	    if (!sheetsById) return null;
592	    const sheetState = readAboutRecord(sheetsById[sheetId]);
593	    if (!sheetState) return null;
594	    const sequence = readAboutRecord(sheetState.sequence);
595	    if (!sequence) return null;
596	    const tracksByObject = readAboutRecord(sequence.tracksByObject);
597	    if (!tracksByObject) return null;
598	    return tracksByObject;
599	  }
600	
601	  private _resolveSheetBinding(sheetId: AboutTheatreSheetId): {
602	    object: AboutTheatreObject;
603	    sequence: TheatreSequencePort;
604	    length: number;
605	  } | null {
606	    const object = this._objectBySheetId.get(sheetId);
607	    const sequence = this._sequenceBySheetId.get(sheetId);
608	    if (!object || !sequence) return null;
609	    return {
610	      object,
611	      sequence,
612	      length: this._lengthBySheetId.get(sheetId) ?? 0,
613	    };
614	  }
615	}
