431	  private _matchFromPrevious(): void {
432	    const currentIndex = ABOUT_THEATRE_SHEET_IDS.indexOf(this._authorSheetId);
433	    if (currentIndex <= 0) {
434	      this._renderStatus("NO PREVIOUS SHEET");
435	      return;
436	    }
437	    const previousSheetId = ABOUT_THEATRE_SHEET_IDS[currentIndex - 1];
438	    const previousObject = this._objectBySheetId.get(previousSheetId) ?? null;
439	    const previousSequence = this._sequenceBySheetId.get(previousSheetId) ?? null;
440	    const currentObject = this._currentObject;
441	    const currentSequence = this._sequenceBySheetId.get(this._authorSheetId) ?? null;
442	    if (!previousObject || !previousSequence || !currentObject || !currentSequence) {
443	      this._renderStatus("MATCH FAILED");
444	      return;
445	    }
446	
447	    const previousEndValues = this._readSheetEndValues(
448	      previousSheetId,
449	      previousObject,
450	      previousSequence,
451	    );
452	    if (!previousEndValues) {
453	      this._renderStatus("MATCH FAILED");
454	      return;
455	    }
456	
457	    this._writeMatchStartKeyframe(
458	      currentObject,
459	      currentSequence,
460	      previousEndValues,
461	    );
462	    this._applyState(previousEndValues);
463	    this._schedulePersistSaveFileSnapshot("MATCH SAVE FAILED");
464	    this._renderStatus(`MATCHED ${previousSheetId.toUpperCase()}`);
465	  }
