473	  private _readSheetEndValues(
474	    sheetId: AboutTheatreSheetId,
475	    object: AboutTheatreObject,
476	    sequence: TheatreSequencePort,
477	  ): AboutTheatreValue | null {
478	    const previousPosition = sequence.position;
479	    try {
480	      sequence.pause();
481	      sequence.position = this._resolveSheetEndPosition(sheetId, sequence);
482	      return pickAboutTheatreValue(mergeAboutTheatreValue(object.value));
483	    } catch (error) {
484	      Logger.warn(CLASS, "_readSheetEndValues", "Failed to read previous sheet end state.", error);
485	      return null;
486	    } finally {
487	      sequence.position = previousPosition;
488	    }
489	  }
490	
491	  private _writeMatchStartKeyframe(
492	    currentObject: AboutTheatreObject,
493	    currentSequence: TheatreSequencePort,
494	    previousValues: AboutTheatreValue,
495	  ): void {
496	    const previousPosition = currentSequence.position;
497	    const scrub = TheatreStudioService.createScrub<
498	      AboutTheatreValue,
499	      AboutTheatreProps
500	    >();
501	    currentSequence.pause();
502	    currentSequence.position = 0;
503	    scrub.capture(({ set }) => {
504	      set(currentObject.props, previousValues);
505	    });
506	    scrub.commit();
507	    currentSequence.position = previousPosition;
508	  }
509	
510	  private _resolveSheetEndPosition(
511	    sheetId: AboutTheatreSheetId,
512	    sequence: TheatreSequencePort,
513	  ): number {
514	    const saveFile = TheatreStudioService.createContentOfSaveFile(
515	      ABOUT_THEATRE_PROJECT_ID,
516	    );
517	    const sheetsById = this._readRecord(saveFile?.sheetsById);
518	    const sheetState = this._readRecord(sheetsById?.[sheetId]);
519	    const sequenceState = this._readRecord(sheetState?.sequence);
520	    const tracksByObject = this._readRecord(sequenceState?.tracksByObject);
521	    const objectTracks = this._readRecord(tracksByObject?.[ABOUT_THEATRE_OBJECT_ID]);
522	    const trackData = this._readRecord(objectTracks?.trackData);
523	    if (!trackData) {
524	      return sequence.length > 0 ? sequence.length : 0;
525	    }
526	
527	    let maxPosition = Number.NEGATIVE_INFINITY;
528	    Object.values(trackData).forEach((trackState) => {
529	      const trackRecord = this._readRecord(trackState);
530	      const keyframes = trackRecord?.keyframes;
531	      if (!Array.isArray(keyframes)) return;
532	      keyframes.forEach((keyframe) => {
533	        const keyframeRecord = this._readRecord(keyframe);
534	        const position = keyframeRecord?.position;
535	        if (typeof position !== "number" || !Number.isFinite(position)) return;
536	        maxPosition = Math.max(maxPosition, position);
537	      });
538	    });
539	
540	    if (!Number.isFinite(maxPosition)) {
541	      return sequence.length > 0 ? sequence.length : 0;
542	    }
543	    return maxPosition;
544	  }
