658	  private _normalizeSavedState(
659	    savedState: Record<string, unknown>,
660	  ): Record<string, unknown> {
661	    const migratedState = this._migrateLegacySheetState(savedState);
662	    const sheetsById = this._readRecord(migratedState.sheetsById);
663	    const cameraSheet = this._readRecord(sheetsById?.[PRIMARY_SHEET_ID]);
664	    const sequence = this._readRecord(cameraSheet?.sequence);
665	    const staticOverrides = this._readRecord(sequence?.staticOverrides);
666	    const objectsByKey = this._readRecord(staticOverrides?.byObject);
667	    const cameraObject = this._readRecord(
668	      objectsByKey?.[ABOUT_THEATRE_OBJECT_ID],
669	    );
670	
671	    if (cameraObject) {
672	      const mergedValues = mergeAboutSceneState(
673	        cameraObject as Partial<typeof ABOUT_DEFAULT_SCENE_STATE>,
674	      );
675	      Object.assign(cameraObject, pickAboutTheatreValue(mergedValues));
676	    }
677	
678	    const projectDefinition = this._readRecord(
679	      savedState.definitionVersion != null ? savedState : null,
680	    );
681	    if (projectDefinition && projectDefinition.addressesBySheetId) {
682	      return { ...migratedState, projectId: ABOUT_THEATRE_PROJECT_ID };
683	    }
684	
685	    return migratedState;
686	  }
687	
688	  private _migrateLegacySheetState(
689	    savedState: Record<string, unknown>,
690	  ): Record<string, unknown> {
691	    const sheetsById = this._readRecord(savedState.sheetsById);
692	    if (!sheetsById) return savedState;
693	
694	    const nextSheetsById: Record<string, unknown> = {};
695	    let didChange = false;
696	
697	    Object.entries(sheetsById).forEach(([sheetId, sheetState]) => {
698	      const mappedSheetId =
699	        LEGACY_ABOUT_SHEET_ID_MAP[sheetId as LegacyAboutSheetId] ?? sheetId;
700	      if (mappedSheetId !== sheetId) {
701	        didChange = true;
702	      }
703	      if ((ABOUT_THEATRE_SHEET_IDS as readonly string[]).includes(mappedSheetId)) {
704	        nextSheetsById[mappedSheetId] = sheetState;
705	        return;
706	      }
707	      didChange = true;
708	    });
709	
710	    if (!didChange) return savedState;
711	
712	    return {
713	      ...savedState,
714	      sheetsById: nextSheetsById,
715	    };
716	  }
717	
718	  private _readRecord(value: unknown): Record<string, unknown> | null {
719	    if (value == null || typeof value !== "object" || Array.isArray(value)) {
720	      return null;
721	    }
722	    return value as Record<string, unknown>;
723	  }
724	
725	  private _minimizeSaveFile(
726	    saveFile: Record<string, unknown>,
727	  ): Record<string, unknown> {
728	    const sheetsById = this._readRecord(saveFile.sheetsById);
729	    if (!sheetsById) return saveFile;
730	    const nextSheetsById: Record<string, unknown> = {};
731	    Object.entries(sheetsById).forEach(([sheetId, sheetState]) => {
732	      if (!this._isTheatreSheetId(sheetId)) return;
733	      const normalizedSheetState = this._normalizeSheetState(
734	        sheetState,
735	        sheetId,
736	      );
737	      if (!normalizedSheetState) return;
738	      nextSheetsById[sheetId] = normalizedSheetState;
739	    });
740	    return {
741	      ...saveFile,
742	      sheetsById: nextSheetsById,
743	    };
744	  }
745	
746	  private _normalizeSheetState(
747	    sheetState: unknown,
748	    sheetId: AboutTheatreSheetId,
749	  ): Record<string, unknown> | null {
750	    const sheetRecord = this._readRecord(sheetState);
751	    if (!sheetRecord) return null;
752	    if (this._sheetHasMeaningfulKeyframes(sheetRecord, sheetId)) {
753	      return sheetRecord;
754	    }
755	    return null;
756	  }
757	
758	  private _sheetHasMeaningfulKeyframes(
759	    sheetState: Record<string, unknown>,
760	    sheetId: AboutTheatreSheetId,
761	  ): boolean {
762	    const sequenceState = this._readRecord(sheetState.sequence);
763	    if (!sequenceState) return false;
764	    const tracksByObject = this._readRecord(sequenceState.tracksByObject);
765	    if (!tracksByObject) return false;
766	    const objectTracks = this._readRecord(tracksByObject[ABOUT_THEATRE_OBJECT_ID]);
767	    if (!objectTracks) return false;
768	    const trackData = this._readRecord(objectTracks.trackData);
769	    if (!trackData) return false;
770	    const sequence = this._sequenceBySheetId.get(sheetId);
771	    if (!sequence) return false;
772	    return Object.values(trackData).some((trackState) =>
773	      this._trackHasMeaningfulKeyframes(trackState, sequence),
774	    );
775	  }
776	
777	  private _trackHasMeaningfulKeyframes(
778	    trackState: unknown,
779	    sequence: TheatreSequencePort,
780	  ): boolean {
781	    const trackRecord = this._readRecord(trackState);
782	    if (!trackRecord) return false;
783	    const keyframes = trackRecord.keyframes;
784	    if (!Array.isArray(keyframes) || keyframes.length === 0) {
785	      return false;
786	    }
787	    const positions = keyframes
788	      .map((keyframe) => {
789	        const keyframeRecord = this._readRecord(keyframe);
790	        const position = keyframeRecord?.position;
791	        return typeof position === "number" && Number.isFinite(position)
792	          ? position
793	          : null;
794	      })
795	      .filter((position): position is number => position != null);
796	    return positions.length > 0;
797	  }
