803	  private _isReadableTheatreState(
804	    value: Record<string, unknown> | null,
805	  ): value is Record<string, unknown> {
806	    if (!value) return false;
807	    const sheetsById = value.sheetsById;
808	    if (
809	      sheetsById == null ||
810	      typeof sheetsById !== "object" ||
811	      Array.isArray(sheetsById)
812	    ) {
813	      return false;
814	    }
815	    return true;
816	  }
